// Decide what to produce. The request's own request_type wins; if the reseller didn't
// specify ('unspecified'), fall back to the client's default service_tier from the registry.
const j = $json;
const rt = j.data && j.data.request_type;
const tier = (j.client_config && j.client_config.service_tier) || 'full_pipeline';
let route = (rt && rt !== 'unspecified') ? rt : tier;
if (!['pricing_only', 'proposal_only', 'full_pipeline'].includes(route)) route = 'full_pipeline';
return [{ json: { ...j, route } }];

// Manual pricing estimate (phase 1 has NO auto hours-estimation engine — explicit non-goal).
// The representative estimate is FILTERED by the request's scope_of_supply: out-of-scope
// categories are dropped so the quote only prices what we're actually supplying.
// scope->cost-category mapping mirrors schemas/scope-catalog.json.
const j = $json;
const scope = (j.data && j.data.scope_of_supply) || {};
const ALL_HOURS = { engineering: 40, assembly: 60, commissioning: 20, project_management: 15 };
const GATE = { engineering: scope.engineering, assembly: scope.installation, commissioning: scope.commissioning, project_management: scope.project_management };
const hours_by_category = {};
for (const k of Object.keys(ALL_HOURS)) { if (GATE[k]) hours_by_category[k] = ALL_HOURS[k]; }
const materials_cost = scope.materials ? 5000 : 0;
return [{ json: { client_id: j.client_id, client_config: j.client_config, data: { materials_cost, hours_by_category } } }];

// pricing_only deliverable: a price estimate (no proposal document). Draft goes to the
// client's own commercial contact (G1), never the extracted end customer.
const j = $json; // Module 3 output: { client_id, client_config, data:<pricing> }
// client_config rides through Module 3 untouched; fall back to the orchestrator's own
// resolution if a future change ever drops it, so the alias can never silently go missing.
const cfg = j.client_config || $('Map Client Config').first().json.client_config || {};
const ec = $('Build Envelope').first().json.email_context || {};
const p = j.data || {};
const recipient = cfg.reply_to || cfg.commercial_contact_email;
if (!recipient) throw new Error(`No reply address for '${j.client_id}' (sender email + commercial_contact_email both empty). Refusing to send the quote to the end customer (gap G1).`);
const m1 = $('Call Module 1').first().json;
const company = (m1.data && m1.data.client && m1.data.client.company) || 'Client';
const cur = p.currency || '';
// Reply inside the reseller's own RFQ thread. Gmail only threads when the threadId AND the
// subject match the original, so a synthetic subject would break out into a new conversation.
const subject = ec.reply_subject || `Price estimate — ${company}`;
const html = `<p>Hi,</p>\n<p>Here is the price estimate for <b>${company}</b>, for your review before it goes to the customer.</p>\n<ul>\n<li>Subtotal: ${p.subtotal} ${cur}</li>\n<li><b>Total: ${p.total} ${cur}</b></li>\n<li>Payment terms: ${p.payment_terms || ''}</li>\n</ul>\n<p>Priced items: ${(p.priced_categories||[]).join(', ') || 'materials'}.</p>`;
const from_alias = cfg.from_alias || '';
if (!from_alias) throw new Error(`No from_alias resolved for '${j.client_id}'. Refusing to send from the raw mailbox address.`);
// Empty string (not null) for threadId: the Gmail node treats it as falsy and omits the
// field, whereas a null would be serialised into the API call.
return [{ json: { client_id: j.client_id, recipient, notification_chat_id: cfg.notification_chat_id, client_status: cfg.status || '', from_alias, send_mode: cfg.send_mode || 'send', thread_id: ec.thread_id || '', subject, html, company, total: p.total, currency: cur } }];

